#!/usr/bin/env bash
# Locate the Swift API generated by Swift Export (after an Xcode/xcodebuild build of the app). bash 3.2 / BSD tools.
# Usage: find-generated-swift.sh <EXPORT_DIR> [symbol-to-grep]
#   symbol: an exact identifier, matched as a whole word (UiState matches `UiState`, not `HomeUiState`);
#   for a substring search grep the files listed in the first section yourself.
#   <EXPORT_DIR> = dir of the module with xcodeIntegration()/swiftPackageIntegration(): ios-export with the
#   umbrella, else <SHARED_DIR>. Paths may contain spaces.
#   e.g. find-generated-swift.sh ios-export             # list generated files
#        find-generated-swift.sh ios-export HomeUiState # also list public declarations naming the type HomeUiState
# Never read stdin: a grep whose file list expands to nothing would otherwise wait forever.
exec </dev/null
set -uo pipefail

MOD="${1:?usage: find-generated-swift.sh <EXPORT_DIR> [symbol]}"
SYM="${2:-}"
BUILD="$MOD/build"

if [ ! -d "$BUILD/SwiftExport" ] && [ ! -d "$BUILD/SPMPackage" ]; then
  echo "No Swift Export output under $BUILD. Build the iOS app through Xcode/xcodebuild first"
  echo "(Swift Export tasks only run with Xcode's environment, via embedSwiftExportForXcode)."
  echo "Wrong dir? With an umbrella pass its dir (<EXPORT_DIR>, e.g. ios-export), not <SHARED_DIR>."
  exit 1
fi

# One Kotlin target is enough to read the API (all targets export the same declarations).
FIRST_TARGET=$(find "$BUILD/SwiftExport" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | sort | head -n 1)

echo "== Generated Swift (per Kotlin target; files/<Module>/<Module>.swift is the module API) =="
find "$BUILD/SwiftExport" -name '*.swift' 2>/dev/null | sort
echo
echo "== Generated Kotlin bridges (errors in compileSwiftExportMainKotlin* point here) =="
find "$BUILD/SwiftExport" -path '*/files/*' -name '*.kt' 2>/dev/null | sort
echo
echo "== Merged static libraries (moduleName in UpperCamelCase, e.g. libShared.a / libCommonExport.a) =="
find "$BUILD/MergedLibraries" -name '*.a' 2>/dev/null | sort

if [ -n "$SYM" ] && [ -n "$FIRST_TARGET" ]; then
  echo
  echo "== Declarations mentioning '$SYM' (first Kotlin target only: $(basename "$FIRST_TARGET")) =="
  # Skip bridge plumbing lines; show public API lines.
  find "$FIRST_TARGET/files" -name '*.swift' 2>/dev/null | sort | while IFS= read -r f; do
    grep -nE "(public|open) .*\b$SYM\b|typealias .*\b$SYM\b|case .*\b$SYM" "$f" 2>/dev/null \
      | grep -vE '__externalRCRef|_bridge|@_cdecl' | awk -v F="$(basename "$f")" '{ print F ":" $0 }' | head -n 60
  done
fi

# Declarations whose generated body is fatalError(): they compile but trap when called from Swift.
# Typical causes: signature mentions a type of a HIDDEN dependency, an unsupported type, or an abstract member
# that a Swift subclass must override. Wrap/reshape the Swift-facing ones (see references/hiding-broken-dependencies.md).
echo
echo "== Declarations with fatalError() bodies (first Kotlin target; runtime/support modules excluded) =="
if [ -n "$FIRST_TARGET" ]; then
  find "$FIRST_TARGET/files" -name '*.swift' 2>/dev/null | sort | while IFS= read -r f; do
    case "$(basename "$f")" in KotlinStdlib.swift|OrgJetbrainsKotlinx*) continue;; esac
    awk -v F="$(basename "$f")" '
      function trim(x) { gsub(/^[ \t]+|[ \t]+$/, "", x); return x }
      /^[ \t]*(public|open|package) .*(func |var |init|subscript)/ {
        decl = trim($0); line = NR; state = ($0 ~ /\{[ \t]*$/) ? "body" : "sig"; next
      }
      state == "sig"  { if ($0 ~ /\{[ \t]*$/) state = "body"; next }
      state == "body" {
        t = trim($0)
        if (t == "get {" || t == "") next
        if (t == "fatalError()") print F ":" line ": " decl
        state = ""
      }
    ' "$f" | grep -vE '__externalRCRef|KotlinBaseConstructionOptions' | head -n 80
  done
fi
